        auto index=raw.data()+256+32*rows;auto weight=index+nodes*4;uint32_t previous=0;for(size_t j=0;j<nodes;j++){uint32_t id;double w;memcpy(&id,index+4*j,4);memcpy(&w,weight+8*j,8);require(id<r[1]&&(!j||id>previous)&&w>0&&std::isfinite(w),"strictly positive finite original-subset weights without index duplication");previous=id;}
