int main(int argc,char**argv){int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);int rank,ranks;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&ranks);try{require(ranks==4&&provided>=MPI_THREAD_FUNNELED,"four actual owner ranks");int code=run(argc,argv,rank);MPI_Finalize();return code;}catch(const std::exception&e){fprintf(stderr,"rank%d INDEPENDENT_RULE_RECORD_AUDIT_FAIL %s\n",rank,e.what());MPI_Abort(MPI_COMM_WORLD,2);return 2;}}
